import Foundation

/// Offline training evidence generated by running the product GomokuBot code,
/// not labels from the synthetic diagram classifier.
/// Every claimed game is re-applied through GomokuState before it may enter
/// the user's separately stored native self-play repertoire.
enum GomokuBundledNativeSeed {
    static let resourceName = "GomokuNativeTrainingSeed"
    static let formatVersion = "veillink.native-gomoku-real-selfplay.v1"

    struct Verified: Sendable {
        let plies: [AdaptiveBoardPly]
        let result: AdaptiveBoardGameResult
    }

    private struct Package: Decodable {
        let format: String
        let engineRevision: String
        let count: Int
        let fnv1a64: String
        let records: [Record]
    }

    private struct Record: Decodable {
        let s: Int
        let m: String
        let r: String
    }

    enum SeedError: Error {
        case empty, invalid, checksumMismatch, illegalGame
    }

    static func verify(from url: URL) throws -> [Verified] {
        let raw = try Data(contentsOf: url, options: .mappedIfSafe)
        guard !raw.isEmpty, raw.count < 3_000_000 else { throw SeedError.invalid }
        let package = try JSONDecoder().decode(Package.self, from: raw)
        guard package.format == formatVersion,
              package.engineRevision == "bc919b454379841180fb8698a9e0addec87e7af0",
              package.count == package.records.count,
              (1...10_000).contains(package.count) else { throw SeedError.invalid }

        var checksum: UInt64 = 14_695_981_039_346_656_037
        for record in package.records {
            guard record.s >= 0, (record.r == "a" || record.r == "h" || record.r == "d") else {
                throw SeedError.invalid
            }
            for byte in "\(record.s)|\(record.r)|\(record.m)\n".utf8 {
                checksum ^= UInt64(byte)
                checksum &*= 1_099_511_628_211
            }
        }
        guard String(checksum, radix: 16) == package.fnv1a64 else {
            throw SeedError.checksumMismatch
        }

        var verified: [Verified] = []
        verified.reserveCapacity(package.count)
        for record in package.records {
            guard let packed = Data(base64Encoded: record.m),
                  (5...GomokuState.size * GomokuState.size).contains(packed.count) else {
                throw SeedError.illegalGame
            }
            var state = GomokuState()
            var plies: [AdaptiveBoardPly] = []
            plies.reserveCapacity(packed.count)
            for byte in packed {
                let before = AdaptiveBoardPosition.gomoku(state)
                let actor = state.currentPlayer
                let index = Int(byte)
                guard state.apply(index: index, actor: actor) else {
                    throw SeedError.illegalGame
                }
                plies.append(AdaptiveBoardPly(
                    position: before, action: String(index), actor: actor
                ))
            }
            let result: AdaptiveBoardGameResult
            switch record.r {
            case "a":
                guard state.winner == .guest else { throw SeedError.illegalGame }
                result = .aiWon
            case "h":
                guard state.winner == .host else { throw SeedError.illegalGame }
                result = .humanWon
            case "d":
                guard state.isDraw else { throw SeedError.illegalGame }
                result = .draw
            default:
                throw SeedError.invalid
            }
            verified.append(Verified(plies: plies, result: result))
        }
        return verified
    }
}